for i in range(10):
  if i == 5:
    break # Прерываем цикл
  if i % 2 == 0:
    continue # Пропускаем четные числа
  print(i)

def factorial(n):
  if n == 0:
    return 1
  else:
    return n * factorial(n-1)

print(factorial(5))
